<script setup lang="ts">import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {getPlatform,getFollowing,getPlatforms,followPlatform,unfollowPlatform,listPlatformPublications} from '../api';import type {FederationPlatform,Publication} from '../types';import {RouterLink} from 'vue-router';import {Network,Users,FileText,ShieldCheck,ArrowRight,Check,Plus} from 'lucide-vue-next';const route=useRoute();const platform=ref<FederationPlatform>();const posts=ref<Publication[]>([]);const loading=ref(true);async function load(){loading.value=true;const id=String(route.params.id);const [p,ps]=await Promise.all([getPlatform(id),listPlatformPublications(id)]);platform.value=p;posts.value=ps;loading.value=false}onMounted(load);async function toggle(){if(!platform.value)return;if(platform.value.isFollowing)await unfollowPlatform(platform.value.id);else await followPlatform(platform.value.id);platform.value=await getPlatform(platform.value.id)}
</script>
<template><div class="page" v-if="platform"><div class="platform-hero card"><div class="platform-logo large">{{platform.name.slice(0,1)}}</div><div class="platform-hero-copy"><div class="eyebrow">Plataforma federada</div><h1>{{platform.name}}</h1><div class="handle">{{platform.handle}}</div><p>{{platform.description}}</p><div class="platform-stats"><span><FileText :size="15"/> {{platform.resourcesCount}} recursos</span><span><Users :size="15"/> {{platform.followersCount}} seguidores</span></div></div><button class="btn" :class="platform.isFollowing?'secondary':'primary'" @click="toggle"><Check v-if="platform.isFollowing" :size="16"/><Plus v-else :size="16"/> {{platform.isFollowing?'Seguindo':'Seguir'}}</button></div><div class="platform-content"><section><div class="section-head"><div><div class="eyebrow">Publicações</div><h2>Recursos desta plataforma</h2></div></div><div class="feed-list"><article v-for="pub in posts" :key="pub.id" class="card publication"><div class="publication-header"><div class="source-logo">{{platform.name.slice(0,1)}}</div><div><strong>{{pub.actorName}}</strong><div class="handle">{{pub.publishedAt.slice(0,16).replace('T',' · ')}}</div></div><span class="federated-pill"><Network :size="13"/> Origem</span></div><div class="publication-body"><h3>{{pub.resource.title}}</h3><p>{{pub.resource.description}}</p><div class="resource-meta"><span><FileText :size="14"/> {{pub.resource.type}}</span><span>{{pub.resource.area}}</span><span class="verified"><ShieldCheck :size="14"/> Verificado</span></div></div><div class="publication-actions"><RouterLink class="btn primary" :to="`/resources/${pub.resource.id}`">Ver recurso <ArrowRight :size="15"/></RouterLink></div></article></div></section></div></div><div v-else class="page"><div class="center">{{loading?'Carregando plataforma…':'Plataforma não encontrada.'}}</div></div></template>
